select jsonb_build_object(
'functions',(select jsonb_agg(jsonb_build_object('name',p.proname,'args',pg_get_function_identity_arguments(p.oid),'result',pg_get_function_result(p.oid),'security_definer',p.prosecdef,'config',p.proconfig,'definition_md5',md5(pg_get_functiondef(p.oid)),'anon_execute',has_function_privilege('anon',p.oid,'EXECUTE'),'authenticated_execute',has_function_privilege('authenticated',p.oid,'EXECUTE'),'service_execute',has_function_privilege('service_role',p.oid,'EXECUTE'))) from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public'),
'triggers',(select jsonb_agg(jsonb_build_object('name',tgname,'enabled',tgenabled,'definition',pg_get_triggerdef(oid))) from pg_trigger where tgrelid='public.staff'::regclass and not tgisinternal),
'constraints',(select jsonb_agg(jsonb_build_object('name',conname,'validated',convalidated,'definition',pg_get_constraintdef(oid))) from pg_constraint where conrelid='public.sync_records'::regclass),
'policies',(select jsonb_agg(to_jsonb(p)) from pg_policies p where schemaname='public' and tablename='sync_records'),
'privileges',(select jsonb_agg(jsonb_build_object('role',role_name,'select',has_table_privilege(role_name,'public.sync_records','SELECT'),'insert',has_table_privilege(role_name,'public.sync_records','INSERT'),'update',has_table_privilege(role_name,'public.sync_records','UPDATE'),'delete',has_table_privilege(role_name,'public.sync_records','DELETE'),'sequence_usage',has_sequence_privilege(role_name,'public.sync_records_server_seq_seq','USAGE'),'sequence_select',has_sequence_privilege(role_name,'public.sync_records_server_seq_seq','SELECT'),'sequence_update',has_sequence_privilege(role_name,'public.sync_records_server_seq_seq','UPDATE'))) from unnest(array['anon','authenticated','service_role']) r(role_name)),
'sync',(select jsonb_build_object('rows',count(*),'max_seq',max(server_seq),'non_objects',count(*) filter(where jsonb_typeof(payload)<>'object'),'mismatched_shops',count(*) filter(where not exists(select 1 from public.shops s where s.id=r.shop_id and s.business_id=r.business_id)),'unknown_tables',count(*) filter(where table_name not in ('products','accounts','settings','events','deliveries','attendance_records','budget_plans','collections_targets','delivery_status_history','physical_cash_counts','daily_close_actions','store_profile')),'data_md5',md5(coalesce(string_agg(to_jsonb(r)::text,'|' order by server_seq),''))) from public.sync_records r),
'counts',jsonb_build_object('businesses',(select count(*) from public.businesses),'shops',(select count(*) from public.shops),'staff',(select count(*) from public.staff),'audit',(select count(*) from public.audit_log),'reconciliation',(select count(*) from public.auth_reconciliation),'auth_users',(select count(*) from auth.users)),
'business_data_md5',(select md5(coalesce(string_agg(to_jsonb(b)::text,'|' order by id),'')) from public.businesses b),
'shop_data_md5',(select md5(coalesce(string_agg(to_jsonb(s)::text,'|' order by id),'')) from public.shops s),
'staff_data_md5',(select md5(coalesce(string_agg(to_jsonb(s)::text,'|' order by id),'')) from public.staff s),
'integrity',jsonb_build_object('active_staff_without_auth',(select count(*) from public.staff where active and terminated_at is null and auth_user_id is null),'businesses_without_active_owner',(select count(*) from public.businesses b where not exists(select 1 from public.staff s where s.business_id=b.id and s.role='owner' and s.active and s.terminated_at is null)))
) as state
